  rw_cells bsegs m q (SpcHdrCells (mkSPC AVP_SPCI_IMPL 1 w 1) j7) -> 0 <= w < 2^31 ->
  aapp q SZ_SPCI_IMPL -> q mod 16 = 0 -> addressable m q SZ_SPCI_IMPL -> (PC + 8 <= q \/ q + SZ_SPCI_IMPL <= PC) ->
