  mem_inv bsegs m -> ACONST m -> stack0 m lo shi -> bv_unsigned sp <= shi ->
  evt bsegs (sci_segA1_post sp gp tp s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc q w lo shi j7 ra s0 s1 s2 m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 PC) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
