Definition sci_vdel_W (lo spz q vb vcap : Z) : list (Z * Z) := [(lo, spz); (q + 80, q + 88); (sh vb, sh vb + vcap)]%Z.

Definition sci_vdel_post (gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (q vb vcap spz lo shi : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR (Z_to_bv 64 ASCI_DEL1_RET) (Z_to_bv 64 spz) gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 vb) (Z_to_bv 64 (8 * vcap)) a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 AOPDEL2) fc None m' (seg_rom bsegs)
    /\ munch (sci_vdel_W lo spz q vb vcap) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo spz
    /\ rw_cells bsegs m' (q + 72) [C8 (Z_to_bv 64 vb); C8 (Z_to_bv 64 vb); C8 (Z_to_bv 64 (vb + 8 * vcap))]
    /\ SHAD m' vb (shadow_of (8 * vcap))
    /\ ACONST m' /\ stack0 m' lo shi.

Lemma sci_vdel : forall (gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (m : mem) (q vb vcap spz lo shi : Z),
  ro_cells bsegs m (spz + 8) [C8 (wz (q + 72))] ->
  rw_cells bsegs m (q + 72) [C8 (wz vb); C8 (wz vb); C8 (wz (vb + 8 * vcap))] ->
  SHAD m vb (cc_shadow (8 * vcap) 0) -> rblock_range vb (8 * vcap) -> 0 < vcap -> 8 * vcap <= 2^16 ->
  aapp q SZ_SPCI_IMPL -> q mod 16 = 0 -> addressable m q SZ_SPCI_IMPL -> (vb + 8 * vcap <= q \/ q + SZ_SPCI_IMPL <= vb) ->
  stk bsegs m lo spz -> lo + 32 + AANNOTATE_VEC_STACK <= spz -> aceil <= lo -> spz mod 16 = 0 ->
  stack0 m lo shi -> spz + 16 <= shi ->
  mem_inv bsegs m -> ACONST m ->
  evt bsegs (sci_vdel_post gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc q vb vcap spz lo shi m)
    (MS (mkR (Z_to_bv 64 ASCI_DEL1_RET) (Z_to_bv 64 spz) gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 (spz + 8)) a1 a2 a3 a4 a5 a6 a7
             s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_VEC_STATEP_DESTROY) fc None m (seg_rom bsegs)).
